replacements.new:
    imagePath: containment?.plasmoid?.backgroundHints === PlasmaCore.Types.NoBackground ? "" : "solid/widgets/panel-background"
}

// VeltOS: the taskbar in the theme and accent colour (TaskbarTint.qml).
TaskbarTint {
    anchors.fill: floatingTranslucentItem
    visible: !root.verticalPanel && containment?.plasmoid?.backgroundHints !== PlasmaCore.Types.NoBackground
}

Keys.onEscapePressed: {

// VeltOS: with a left-aligned taskbar (Settings > Personalization >
// Taskbar) Start and search open at the left, over their own button,
// as Windows 11 does; their button then sits at the screen's left
// edge, while centred buttons start well inside the taskbar.
function startPopupParent() {
    if (!["org.veltos.startmenu", "org.veltos.search"].includes(Plasmoid.pluginName) || !startCentre.parent)
        return root.compactRepresentation;
    const window = root.Window.window;
    const left = root.mapToItem(null, 0, 0).x;
    return window && left > window.width * 0.12 ? startCentre : root.compactRepresentation;
}

// VeltOS: Start opens centred over the taskbar, like Windows 11. The
// popup is placed over its visual parent; this empty item sits in the
// middle of the panel window, which spans the screen.
Item {
    id: startCentre
    parent: root.Window.window ? root.Window.window.contentItem : null
    x: parent ? Math.round(parent.width / 2) - 1 : 0
    width: 2
    height: parent ? parent.height : 0
}

PlasmaCore.AppletPopup {
    id: dialog
    objectName: "popupWindow"

// Read again each time the popup opens (dialog.visible): the
// taskbar may have been aligned to the left since.
visualParent: dialog.visible, root.startPopupParent()

// VeltOS: no second box. VeltOS' taskbar buttons draw their own
// pressed backdrop (Start, quick settings, the clock), and Windows 11
// draws none behind the search box; Plasma's box around them made a
// box inside a box (product owner, 2026-10-23).
opacity: plasmoidItem && plasmoidItem.expanded
         && !["org.veltos.search", "org.veltos.startmenu", "org.veltos.quicksettings",
              "org.veltos.clock"].includes(Plasmoid.pluginName) ? 1 : 0

objectName: "popupWindow"
// VeltOS: Start and the other flyouts slide in from the taskbar,
// like Windows 11 (KWin's sliding popups effect).
animated: true
